const halbiVocab=[{english:"Hello / Greetings",halbi:"Johar",script:"जोहार",pronunciation:"Johar"},{english:"Water",halbi:"Pani",script:"पानी",pronunciation:"Pani"},{english:"Rice",halbi:"Bhat",script:"भात",pronunciation:"Bhaat"},{english:"House",halbi:"Ghar",script:"घर",pronunciation:"Ghar"},{english:"Mother",halbi:"Mai",script:"माई",pronunciation:"Ma-i"},{english:"Elder Brother",halbi:"Dada",script:"दादा",pronunciation:"Dada"},{english:"Forest",halbi:"Jangal",script:"जंगल",pronunciation:"Jangal"},{english:"Village",halbi:"Gaon",script:"गाँव",pronunciation:"Gaon"},{english:"Food",halbi:"Khana",script:"खाना",pronunciation:"Khana"},{english:"Child",halbi:"Baccha",script:"बच्चा",pronunciation:"Baccha"}];document.addEventListener("DOMContentLoaded",()=>{const i=document.getElementById("vocab-grid");let n=window.speechSynthesis;halbiVocab.forEach(a=>{const t=document.createElement("div");t.className="vocab-card",t.innerHTML=`\n            <div class="card-inner">\n                \x3c!-- Front of Card --\x3e\n                <div class="card-front">\n                    <div class="word-english">${a.english}</div>\n                    <div class="click-hint">Click to flip</div>\n                </div>\n                \x3c!-- Back of Card --\x3e\n                <div class="card-back">\n                    <div class="word-kurmali">${a.halbi}</div> \x3c!-- Kept class name for generic styling --\x3e\n                    <div class="word-script">${a.script}</div>\n                    <button class="audio-btn" data-speak="${a.pronunciation}" aria-label="Listen to pronunciation">🔊</button>\n                </div>\n            </div>\n        `,t.addEventListener("click",i=>{i.target.closest(".audio-btn")||t.classList.toggle("is-flipped")});const e=t.querySelector(".audio-btn");e.addEventListener("click",i=>{i.stopPropagation();const a=e.getAttribute("data-speak");n.speaking&&n.cancel();const t=new SpeechSynthesisUtterance(a),c=n.getVoices().find(i=>i.lang.includes("hi-IN")||i.lang.includes("hi"));c&&(t.voice=c),t.rate=.9,n.speak(t)}),i.appendChild(t)})});